CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'manager',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS warehouses(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,code TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,sku TEXT UNIQUE NOT NULL,category TEXT NOT NULL,uom TEXT NOT NULL,reorder_point REAL NOT NULL DEFAULT 0,reorder_qty REAL NOT NULL DEFAULT 0,lead_time_days INTEGER NOT NULL DEFAULT 7,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,warehouse_id INTEGER NOT NULL,quantity REAL NOT NULL DEFAULT 0,UNIQUE(product_id,warehouse_id));
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',warehouse_id INTEGER NOT NULL,partner TEXT,reference TEXT,created_by INTEGER NOT NULL,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE IF NOT EXISTS document_lines(id INTEGER PRIMARY KEY AUTOINCREMENT,document_id INTEGER NOT NULL,product_id INTEGER NOT NULL,quantity REAL NOT NULL,batch TEXT,expiry TEXT);
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,warehouse_id INTEGER NOT NULL,delta REAL NOT NULL,before_qty REAL NOT NULL,after_qty REAL NOT NULL,source_type TEXT NOT NULL,source_id INTEGER NOT NULL,reason TEXT,created_by INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS otps(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id INTEGER,metadata TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_preferences(user_id INTEGER PRIMARY KEY,theme TEXT NOT NULL DEFAULT 'light',email_notifications INTEGER NOT NULL DEFAULT 1,low_stock_alerts INTEGER NOT NULL DEFAULT 1,anomaly_alerts INTEGER NOT NULL DEFAULT 1,daily_digest INTEGER NOT NULL DEFAULT 0,compact_mode INTEGER NOT NULL DEFAULT 0,default_warehouse_id INTEGER);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,type TEXT NOT NULL DEFAULT 'info',title TEXT NOT NULL,message TEXT NOT NULL,action TEXT,read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
